lab.code:
# 元素周期表前 10 号探索台
num = 1   # 原子序数

hide()
# 10 块元素瓷砖（按类别着色，选中变红）
i = 1
while i < 11:
    col = i - (i / 5) * 5
    row = i / 5
    x = -130 + col * 56
    y = 60 - row * 66
    tile = "#94a3b8"
    if i < 3:
        tile = "#5eead4"
    if i == 2:
        tile = "#c4b5fd"
    if i == 5:
        tile = "#fdba74"
    if i == 6:
        tile = "#a3a3a3"
    if i == 7:
        tile = "#5eead4"
    if i == 8:
        tile = "#fca5a5"
    if i == 9:
        tile = "#c4b5fd"
    if i == 10:
        tile = "#c4b5fd"
    if i == num:
        tile = "#dc2626"
    fill_rect(x + 24, y - 26, 48, 52, tile)
    write(i, x + 24, y - 8, "#ffffff", 12)
    i = i + 1
# 元素名片
name = ""
if num == 1:
    name = "氢 H：宇宙最多"
if num == 2:
    name = "氦 He：气球安全气"
if num == 3:
    name = "锂 Li：电池心脏"
if num == 4:
    name = "铍 Be：轻而硬"
if num == 5:
    name = "硼 B：洗涤剂"
if num == 6:
    name = "碳 C：钻石铅笔芯"
if num == 7:
    name = "氮 N：空气 78%"
if num == 8:
    name = "氧 O：生命之气"
if num == 9:
    name = "氟 F：牙膏防蛀"
if num == 10:
    name = "氖 Ne：霓虹灯"
write(name, -190, 145, "#dc2626", 13)
write(num + " 号", -190, 120, "#0f172a", 14)
write("红=选中｜青=非金属 紫稀有灰金属", -200, -140, "#64748b", 10)
write("原子序数 = 质子数 = 核外电子数", -200, -155, "#1d4ed8", 10)
